def compute(vars):
    receivable = vars["v2"]
    doubtful_allowance = vars["v1"]

    if receivable == 0:
        return None

    doubtful_receivables = -doubtful_allowance
    percentage = doubtful_receivables / receivable * 100

    return {
        "value": percentage,
        "trace": {
            "doubtful_receivables": doubtful_receivables,
            "trade_and_other_accounts_receivable": receivable,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
